function purchaseLines(){return [...$('mgmt-order-lines').children].map(row=>{const inputs=row.querySelectorAll('input'),product=data.products.find(p=>String(p.id)===row.querySelector('select').value);if(!product)throw Error('Selecciona un producto en cada partida');const qty=Number(inputs[0].value),cost=Number(inputs[1].value),lot=inputs[2].value.trim(),expiry=inputs[3].value,serials=inputs[4].value.split(',').map(s=>s.trim()).filter(Boolean);if(!Number.isFinite(qty)||qty<=0||Math.abs(qty*1000-Math.round(qty*1000))>.00001||!Number.isFinite(cost)||cost<0||Math.abs(cost*100-Math.round(cost*100))>.00001)throw Error('Revisa cantidades y costos');if(/[|~{}]/.test(lot))throw Error('El lote no puede incluir | ~ { }');if(product.pzModo==='i'&&(!Number.isInteger(qty)||serials.length!==qty||new Set(serials.map(s=>s.toUpperCase())).size!==serials.length))throw Error('Cada pieza individual requiere su código nuevo y una cantidad entera');if(serials.some(s=>!/^[-A-Za-z0-9_.]{1,100}$/.test(s)))throw Error('Usa códigos individuales sin espacios ni caracteres especiales');return {product_id:product.id,description:product.nombre,quantity:qty,unit_cost:cost,lot,expiry,serials};});}
