window.cpManagementPayment=function(id){if(!can('expenses')||!ready)return;const a=data.accounts.find(a=>a.id===id);if(!a||a.status!=='abierta')return;const balance=accountBalance(a);if(!showEditor('payment',id,'Registrar abono · '+a.party,`<div class="cp-ops-total">Saldo pendiente: ${money(balance)}</div>`+grid(field('amount','Importe del abono MXN',balance,'number',true)+field('paid_on','Fecha de pago',day(),'date',true)+select('method','Método',['Efectivo','Transferencia','Tarjeta','Depósito','Otro'],'Transferencia',true)+field('reference','Referencia / comprobante'))+`<p class="cp-ops-note">${a.kind==='pagar'?'Se registrará el abono y un gasto vinculado en una sola operación.':'Se reducirá el saldo de la cuenta, sin volver a registrar una venta.'} Confirma que el pago ya se realizó.</p>`))return;$('mgmt-amount').max=balance;$('mgmt-paid_on').max=day();};
